ALTER TABLE restaurants ADD COLUMN IF NOT EXISTS legal_name TEXT;
ALTER TABLE restaurants ADD COLUMN IF NOT EXISTS description TEXT;
ALTER TABLE restaurants ADD COLUMN IF NOT EXISTS email TEXT;
ALTER TABLE restaurants ADD COLUMN IF NOT EXISTS website TEXT;
ALTER TABLE restaurants ADD COLUMN IF NOT EXISTS default_language TEXT NOT NULL DEFAULT 'EN';
ALTER TABLE restaurants ADD COLUMN IF NOT EXISTS supported_languages JSONB NOT NULL DEFAULT '["EN","ES"]';
CREATE TABLE IF NOT EXISTS business_hours (id UUID PRIMARY KEY, restaurant_id UUID NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE, weekday INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6), start_time TIME NOT NULL, end_time TIME NOT NULL, CHECK(start_time < end_time), UNIQUE(restaurant_id,weekday,start_time,end_time));
CREATE TABLE IF NOT EXISTS special_closures (id UUID PRIMARY KEY, restaurant_id UUID NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE, closure_date DATE NOT NULL, start_time TIME, end_time TIME, reason TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS menu_categories (id UUID PRIMARY KEY, restaurant_id UUID NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT, display_order INTEGER NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(restaurant_id,name));
CREATE TABLE IF NOT EXISTS menu_items (id UUID PRIMARY KEY, restaurant_id UUID NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE, category_id UUID NOT NULL REFERENCES menu_categories(id) ON DELETE RESTRICT, name TEXT NOT NULL, description TEXT, price_cents INTEGER NOT NULL CHECK(price_cents>=0), active BOOLEAN NOT NULL DEFAULT TRUE, available BOOLEAN NOT NULL DEFAULT TRUE, unavailable_reason TEXT, dietary_information JSONB NOT NULL DEFAULT '[]', allergens JSONB NOT NULL DEFAULT '[]', display_order INTEGER NOT NULL DEFAULT 0, UNIQUE(restaurant_id,name));
CREATE TABLE IF NOT EXISTS modifier_groups (id UUID PRIMARY KEY, restaurant_id UUID NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE, menu_item_id UUID NOT NULL REFERENCES menu_items(id) ON DELETE CASCADE, name TEXT NOT NULL, required BOOLEAN NOT NULL DEFAULT FALSE, min_selections INTEGER NOT NULL DEFAULT 0, max_selections INTEGER NOT NULL DEFAULT 1, display_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS modifier_options (id UUID PRIMARY KEY, restaurant_id UUID NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE, modifier_group_id UUID NOT NULL REFERENCES modifier_groups(id) ON DELETE CASCADE, name TEXT NOT NULL, price_delta_cents INTEGER NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, display_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS faqs (id UUID PRIMARY KEY, restaurant_id UUID NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE, question TEXT NOT NULL, answer TEXT NOT NULL, category TEXT, active BOOLEAN NOT NULL DEFAULT TRUE, priority INTEGER NOT NULL DEFAULT 0, display_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS restaurant_policies (id UUID PRIMARY KEY, restaurant_id UUID NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE, policy_type TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(restaurant_id,policy_type,title));
CREATE TABLE IF NOT EXISTS restaurant_settings (restaurant_id UUID PRIMARY KEY REFERENCES restaurants(id) ON DELETE CASCADE, parking JSONB NOT NULL DEFAULT '{}', directions JSONB NOT NULL DEFAULT '{}', reservation_rules JSONB NOT NULL DEFAULT '{}', escalation JSONB NOT NULL DEFAULT '{}', ai_configuration JSONB NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS brain_hours_tenant_idx ON business_hours(restaurant_id,weekday); CREATE INDEX IF NOT EXISTS brain_menu_tenant_idx ON menu_items(restaurant_id,category_id); CREATE INDEX IF NOT EXISTS brain_faq_tenant_idx ON faqs(restaurant_id);
